// GatewayServiceClient is a client for the pantherclaw.v1.GatewayService service.
type GatewayServiceClient interface {
	// Enroll exchanges a single-use enrollment token and a certificate
	// request, signed by a key the gateway generated, for a 24-hour client
	// certificate (HR-180).
	// permission: gateway.enroll
	Enroll(context.Context, *v1.GatewayServiceEnrollRequest) (*v1.GatewayServiceEnrollResponse, error)
	// RenewCertificate issues a new certificate for a new key; the current one
	// is accepted for 10 more minutes.
	// permission: gateway.sync
	RenewCertificate(context.Context, *v1.RenewCertificateRequest) (*v1.RenewCertificateResponse, error)
	// RegisterBrokerKey registers the gateway's X-Wing broker public key
	// (HR-182). Registering the active key again changes nothing.
	// permission: gateway.sync
	RegisterBrokerKey(context.Context, *v1.RegisterBrokerKeyRequest) (*v1.RegisterBrokerKeyResponse, error)
	// GetConfiguration returns what this gateway serves: its connections and
	// route modes, the packages they pin, and their sealed credentials.
	// permission: gateway.sync
	GetConfiguration(context.Context, *v1.GetConfigurationRequest) (*v1.GetConfigurationResponse, error)
	// WatchContainment streams the org's containment state: a snapshot first,
	// then the state again on every change and a heartbeat every 500 ms
	// (HR-010). A gateway whose last message is older than 2 seconds stops
	// dispatching.
	// permission: gateway.sync
	WatchContainment(context.Context, *v1.WatchContainmentRequest) (GatewayServiceWatchContainmentClientStream, error)
	// ReportConnectorState reports a run of one of the calling gateway's
	// connectors (G0 M9 track C): its spec revision, container, engine and
	// state, which moves only forward. The org and gateway come from the
	// certificate alone; only a connector connection that gateway serves is
	// accepted.
	// permission: gateway.observe
	ReportConnectorState(context.Context, *v1.ReportConnectorStateRequest) (*v1.ReportConnectorStateResponse, error)
	// ReportCircuit reports that a connection's circuit breaker opened
	// (HR-078); the server quarantines the connection.
	// permission: gateway.observe
	ReportCircuit(context.Context, *v1.ReportCircuitRequest) (*v1.ReportCircuitResponse, error)
	// ReportDrift reports that an upstream MCP server's tool no longer matches
	// the reviewed package (HR-081); the server quarantines the org's pin of
	// that package version.
	// permission: gateway.observe
	ReportDrift(context.Context, *v1.ReportDriftRequest) (*v1.ReportDriftResponse, error)
	// ClaimVerifications leases due verification tasks of the calling
	// gateway's connections (G0 M7, HR-190): each lease is single use, lasts
	// at most 30 s and names a reviewed read the gateway makes with the
	// connection's credential. Nothing is leased under containment.
	// permission: gateway.verify
	ClaimVerifications(context.Context, *v1.ClaimVerificationsRequest) (*v1.ClaimVerificationsResponse, error)
	// MintTestActionTokens mints, under the calling gateway's live lease of
	// a target_verifier connection test, test-purpose action tokens for the
	// package's test read only (G0 M8, N15): one binding the read's empty
	// body and one binding another body. Any other lease is refused.
	// permission: gateway.verify
	MintTestActionTokens(context.Context, *v1.MintTestActionTokensRequest) (*v1.MintTestActionTokensResponse, error)
	// ReportObservation reports what a leased read observed: only the fields
	// the verifier declares, and a digest of the answer (HR-190).
	// permission: gateway.verify
	ReportObservation(context.Context, *v1.ReportObservationRequest) (*v1.ReportObservationResponse, error)
	// ReportFacts records what the gateway read from a connection's system of
	// record before a decision, as that connection's registered fact provider:
	// only the facts the provider declares, about the connection's targets
	// (G0 M8 decision 5, HR-160).
	// permission: gateway.facts.report
	ReportFacts(context.Context, *v1.ReportFactsRequest) (*v1.ReportFactsResponse, error)
	// ReportRevocationFailure records that an installation token the gateway
	// minted for a fact read, a verification read or an organization scan
	// could not be revoked: it lasts until its expiry (ADR-0021 item 6,
	// R-18). A dispatch's token is reported with its outcome instead.
	// permission: gateway.observe
	ReportRevocationFailure(context.Context, *v1.ReportRevocationFailureRequest) (*v1.ReportRevocationFailureResponse, error)
	// ReportLocalRefusal reports an action the gateway refused on its own
	// before asking the Authority, as a security signal for detections
	// (G0 M12, HR-225): only machine metadata (the connection, the refusal
	// code, the operation and the run), never the payload or the secret. The
	// server records connection.secret_in_payload_refused for a connection
	// the gateway serves.
	// permission: gateway.observe
	ReportLocalRefusal(context.Context, *v1.ReportLocalRefusalRequest) (*v1.ReportLocalRefusalResponse, error)
	// ReportStatus reports one gateway replica's status (G0 M15 D10,
	// HR-410): its version, build, start time, the config version it serves
	// and each connection's serving state. The org and gateway come from the
	// certificate alone; connections the gateway does not serve are dropped.
	// A failed report never stops the gateway serving.
	// permission: gateway.observe
	ReportStatus(context.Context, *v1.ReportStatusRequest) (*v1.ReportStatusResponse, error)
	// PutMCPState writes one MCP hold, task or session of the calling
	// gateway (G0 M15 D12, HR-411..413), compare-and-set on if_version. An
	// update keeps the entry's binding, and a connection the gateway does
	// not serve is refused (D42).
	// permission: gateway.sync
	PutMCPState(context.Context, *v1.PutMCPStateRequest) (*v1.PutMCPStateResponse, error)
	// GetMCPState reads one live MCP hold, task or session of the calling
	// gateway; an expired entry is not found.
	// permission: gateway.sync
	GetMCPState(context.Context, *v1.GetMCPStateRequest) (*v1.GetMCPStateResponse, error)
	// DeleteMCPState deletes one MCP hold, task or session of the calling
	// gateway; a missing entry is not an error.
	// permission: gateway.sync
	DeleteMCPState(context.Context, *v1.DeleteMCPStateRequest) (*v1.DeleteMCPStateResponse, error)
	// ReportInventory reports what an upstream MCP server lists behind one
	// of the calling gateway's kind-mcp connections (F352, G0 M15 D20): its
	// tools, resources and resource templates. A new item no active reviewed
	// package version covers opens a TOOL_REVIEW entry and stays inert
	// (HR-414); descriptions are UNTRUSTED (HR-415). Reports are capped and
	// accepted only for connections the gateway serves (HR-418).
	// permission: gateway.observe
	ReportInventory(context.Context, *v1.ReportInventoryRequest) (*v1.ReportInventoryResponse, error)
}

