// RegisterGatewayServiceHandler registers svc as the pantherclaw.v1.GatewayService implementation
// on server.
func RegisterGatewayServiceHandler(server *connect.Server, svc GatewayServiceHandler) {
	adapter := gatewayServiceHandler{svc: svc}
	server.Register(
		connect.Method{Spec: gatewayServiceEnrollSpec(), Handler: adapter.enroll},
		connect.Method{Spec: gatewayServiceRenewCertificateSpec(), Handler: adapter.renewCertificate},
		connect.Method{Spec: gatewayServiceRegisterBrokerKeySpec(), Handler: adapter.registerBrokerKey},
		connect.Method{Spec: gatewayServiceGetConfigurationSpec(), Handler: adapter.getConfiguration},
		connect.Method{Spec: gatewayServiceWatchContainmentSpec(), Handler: adapter.watchContainment},
		connect.Method{Spec: gatewayServiceReportConnectorStateSpec(), Handler: adapter.reportConnectorState},
		connect.Method{Spec: gatewayServiceReportCircuitSpec(), Handler: adapter.reportCircuit},
		connect.Method{Spec: gatewayServiceReportDriftSpec(), Handler: adapter.reportDrift},
		connect.Method{Spec: gatewayServiceClaimVerificationsSpec(), Handler: adapter.claimVerifications},
		connect.Method{Spec: gatewayServiceMintTestActionTokensSpec(), Handler: adapter.mintTestActionTokens},
		connect.Method{Spec: gatewayServiceReportObservationSpec(), Handler: adapter.reportObservation},
		connect.Method{Spec: gatewayServiceReportFactsSpec(), Handler: adapter.reportFacts},
		connect.Method{Spec: gatewayServiceReportRevocationFailureSpec(), Handler: adapter.reportRevocationFailure},
		connect.Method{Spec: gatewayServiceReportLocalRefusalSpec(), Handler: adapter.reportLocalRefusal},
		connect.Method{Spec: gatewayServiceReportStatusSpec(), Handler: adapter.reportStatus},
		connect.Method{Spec: gatewayServicePutMCPStateSpec(), Handler: adapter.putMCPState},
		connect.Method{Spec: gatewayServiceGetMCPStateSpec(), Handler: adapter.getMCPState},
		connect.Method{Spec: gatewayServiceDeleteMCPStateSpec(), Handler: adapter.deleteMCPState},
		connect.Method{Spec: gatewayServiceReportInventorySpec(), Handler: adapter.reportInventory},
	)
}

